
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_hcth_407_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_hcth_407", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.523780815531722e+00, -4.432529819351734e+00, -4.304758516283227e+00, -4.127970791473162e+00, -3.887547004884305e+00, -3.568672248670968e+00, -3.160984578341036e+00, -2.667631120618729e+00, -2.120376110670505e+00, -1.592469820510615e+00, -1.121678297398903e+00, -7.738410863138340e-01, -6.694524553739801e-01, -5.442300107053870e-01, -3.963980270408963e-01, -2.580436764492816e-01, -1.422463779762696e-01, -8.089645462389174e-02, -2.272192584162067e-02, -2.875550472382196e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


